#!/usr/bin/env python3
"""Turn an LH2 capture recording into a host-test fixture.

A recording is what a bootloader built with DB_LH2_CAPTURE_RTT writes to RTT
up-buffer 1, saved by the J-Link RTT logger: a stream of 80-byte records
(db_lh2_capture_record() in drv/lh2_decoder.h). This script checks the
stream and writes up to 500 captures as a C header under tests/lh2_fixtures/,
then rewrites tests/lh2_fixtures.h, the index test_lh2_replay.c includes.

    python3 dist/scripts/lh2/lh2_capture.py rec.bin --name spot-8aad \\
        --robot 8AAD --spot "(263, 600)" --channels 0,1 --date 2026-11-12
    python3 dist/scripts/lh2/lh2_capture.py rec.bin --check
    python3 dist/scripts/lh2/lh2_capture.py --self-test
"""

from __future__ import annotations

import argparse
import re
import struct
import sys
from dataclasses import dataclass
from pathlib import Path

RECORD_BYTES = 80
MAGIC = 0x324C
CAPTURE_BYTES = 64
MAX_CAPTURES = 500
ROOT = Path(__file__).resolve().parents[3]
FIXTURES = ROOT / "tests" / "lh2_fixtures"
INDEX = ROOT / "tests" / "lh2_fixtures.h"

# A record db_lh2_capture_record() wrote on the host; the self-test and
# test_lh2_replay.c both check against it
GOLDEN_RECORD = bytes.fromhex(
    "4c32"
    "efcdab89"
    "78563412"
    "0300"
    "0700"
    + "".join(f"{i:02x}" for i in range(64))
    + "6c0c"
)


@dataclass
class Record:
    sequence: int
    t_us: int
    queue_dropped: int
    record_dropped: int
    spi: bytes


def checksum(data: bytes) -> int:
    return sum(data) & 0xFFFF


def encode(r: Record) -> bytes:
    body = struct.pack(
        "<HIIHH", MAGIC, r.sequence, r.t_us, r.queue_dropped, r.record_dropped
    )
    body += r.spi
    return body + struct.pack("<H", checksum(body))


def parse(data: bytes) -> tuple[list[Record], int]:
    """The valid records, in order, and the bytes skipped resynchronising."""
    records: list[Record] = []
    skipped = 0
    i = 0
    while i + RECORD_BYTES <= len(data):
        chunk = data[i : i + RECORD_BYTES]
        magic, seq, t_us, qd, rd = struct.unpack_from("<HIIHH", chunk)
        (sum_,) = struct.unpack_from("<H", chunk, RECORD_BYTES - 2)
        if magic == MAGIC and sum_ == checksum(chunk[:-2]):
            records.append(Record(seq, t_us, qd, rd, chunk[14 : 14 + CAPTURE_BYTES]))
            i += RECORD_BYTES
        else:
            i += 1
            skipped += 1
    return records, skipped + (len(data) - i)


def report(records: list[Record], skipped: int) -> list[str]:
    lines = [f"{len(records)} records, {skipped} bytes skipped"]
    if not records:
        return lines
    gaps = [
        (a.sequence, b.sequence)
        for a, b in zip(records, records[1:])
        if b.sequence != (a.sequence + 1) & 0xFFFFFFFF
    ]
    lines.append(
        f"sequence {records[0].sequence} to {records[-1].sequence}, {len(gaps)} gaps"
    )
    lines.append(
        f"queue drops {records[-1].queue_dropped - records[0].queue_dropped}, "
        f"recording drops {records[-1].record_dropped - records[0].record_dropped}"
    )
    span = (records[-1].t_us - records[0].t_us) & 0xFFFFFFFF
    lines.append(f"{span / 1e6:.3f} s of captures")
    return lines


def c_name(name: str) -> str:
    return re.sub(r"[^a-z0-9]", "_", name.lower())


def fixture_text(name: str, records: list[Record], meta: dict[str, str]) -> str:
    ident = c_name(name)
    out = [
        "/*",
        " * Generated by dist/scripts/lh2/lh2_capture.py; do not edit.",
        " *",
    ]
    out += [f" * {k}: {v}" for k, v in meta.items()]
    out += [" */", "", "// clang-format off", f"static const lh2_fixture_capture_t lh2_fixture_{ident}[] = {{"]
    for r in records:
        hexes = ", ".join(f"0x{b:02x}" for b in r.spi)
        out.append(f"    {{ {r.t_us}U, {{ {hexes} }} }},")
    out += ["};", "// clang-format on", ""]
    return "\n".join(out)


def index_text(fixtures: list[tuple[str, dict[str, str]]]) -> str:
    out = [
        "/*",
        " * Generated by dist/scripts/lh2/lh2_capture.py; do not edit.",
        " * The recorded LH2 captures test_lh2_replay.c replays.",
        " */",
        "",
        "#ifndef __LH2_FIXTURES_H",
        "#define __LH2_FIXTURES_H",
        "",
        "#include <stddef.h>",
        "#include <stdint.h>",
        "",
        "typedef struct {",
        "    uint32_t t_us;",
        "    uint8_t  spi[64];",
        "} lh2_fixture_capture_t;",
        "",
        "typedef struct {",
        "    const char                  *name;",
        "    const char                  *source;  ///< recorded on a robot, or synthetic",
        "    const lh2_fixture_capture_t *captures;",
        "    size_t                       count;",
        "} lh2_fixture_t;",
        "",
    ]
    for name, _ in fixtures:
        out.append(f'#include "lh2_fixtures/{name}.h"')
    out += ["", "// clang-format off", "static const lh2_fixture_t lh2_fixtures[] = {"]
    for name, meta in fixtures:
        ident = c_name(name)
        src = meta.get("source", "recorded").replace('"', "'")
        out.append(
            f'    {{ "{name}", "{src}", lh2_fixture_{ident}, '
            f"sizeof(lh2_fixture_{ident}) / sizeof(lh2_fixture_{ident}[0]) }},"
        )
    out += ["};", "// clang-format on", "", "#endif", ""]
    return "\n".join(out)


def read_meta(path: Path) -> dict[str, str]:
    meta = {}
    for line in path.read_text().splitlines()[3:]:
        m = re.match(r" \* ([a-z]+): (.*)", line)
        if not m:
            break
        meta[m.group(1)] = m.group(2)
    return meta


def write_index() -> None:
    fixtures = [(p.stem, read_meta(p)) for p in sorted(FIXTURES.glob("*.h"))]
    INDEX.write_text(index_text(fixtures))


def self_test() -> int:
    r = Record(0x89ABCDEF, 0x12345678, 3, 7, bytes(range(64)))
    assert encode(r) == GOLDEN_RECORD, encode(r).hex()
    noise = b"\x00\x4c\x99" + encode(r) + b"\x4c\x32\x00" + encode(
        Record(r.sequence + 2, r.t_us + 9, 3, 8, bytes(64))
    )
    records, skipped = parse(noise)
    assert [x.sequence for x in records] == [r.sequence, r.sequence + 2], records
    assert skipped == 6, skipped
    assert report(records, skipped)[1].endswith("1 gaps")
    text = fixture_text("x-y", records, {"source": "synthetic"})
    assert "lh2_fixture_x_y[]" in text and text.count("U, {") == 2
    print("lh2_capture self-test: passed")
    return 0


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("recording", nargs="?", type=Path)
    ap.add_argument("--name", help="fixture name, e.g. spot-8aad")
    ap.add_argument("--robot", help="the robot's id tail, e.g. 8AAD")
    ap.add_argument("--spot", help="where it stood")
    ap.add_argument("--channels", help="the stations' channels, e.g. 0,1")
    ap.add_argument("--date", help="the recording's date")
    ap.add_argument("--source", default="recorded", help="recorded or synthetic")
    ap.add_argument("--first", type=int, default=0, help="first record to keep")
    ap.add_argument("--check", action="store_true", help="only report")
    ap.add_argument("--self-test", action="store_true")
    args = ap.parse_args()
    if args.self_test:
        return self_test()
    if not args.recording:
        ap.error("a recording is needed")
    records, skipped = parse(args.recording.read_bytes())
    print("\n".join(report(records, skipped)))
    if args.check:
        return 0
    if not args.name:
        ap.error("--name is needed to write a fixture")
    kept = records[args.first : args.first + MAX_CAPTURES]
    meta = {
        "source": args.source,
        "recording": args.recording.name,
        "robot": args.robot or "-",
        "spot": args.spot or "-",
        "channels": args.channels or "-",
        "date": args.date or "-",
        "captures": f"{len(kept)} of {len(records)}, from record {args.first}",
    }
    FIXTURES.mkdir(parents=True, exist_ok=True)
    (FIXTURES / f"{args.name}.h").write_text(fixture_text(args.name, kept, meta))
    write_index()
    print(f"wrote tests/lh2_fixtures/{args.name}.h and tests/lh2_fixtures.h")
    return 0


if __name__ == "__main__":
    sys.exit(main())
